// Simulasi data kandidat (dummy)
const candidates = [
  {
    candidate_name: "Budi",
    position: "Backend Engineer",
    claimed_skills: ["Node.js", "PostgreSQL", "Docker", "REST API"],
    past_company_type: "Startup"
  },
  {
    candidate_name: "Siti",
    position: "DevOps Engineer",
    claimed_skills: ["Kubernetes", "CI/CD", "Linux", "AWS"],
    past_company_type: "Enterprise"
  }
];

return candidates.map(c => ({ json: c }));

// Prompt Builder: menyusun instruksi dinamis dari profil & skill kandidat
return $input.all().map(item => {
  const c = item.json;
  const user_prompt =
`Profil kandidat:
- Nama: ${c.candidate_name}
- Posisi dilamar: ${c.position}
- Skill yang diklaim: ${c.claimed_skills.join(", ")}
- Tipe perusahaan sebelumnya: ${c.past_company_type}

Buatkan SATU pertanyaan studi kasus teknis (troubleshooting) yang relevan dengan skill dan posisi di atas.`;

  return { json: { ...c, user_prompt } };
});

// Mock Jawaban: simulasi dua kualitas jawaban (bagus vs buruk) untuk pengujian
const questions = $input.all();
const profiles = $('Prompt Builder').all();

return questions.map((q, i) => {
  const profile = profiles[i].json;
  let candidate_answer;

  if (profile.candidate_name === "Budi") {
    // Jawaban berkualitas: langkah teknis mendalam
    candidate_answer =
      "Pertama saya cek log aplikasi dan metrik (CPU, memori, koneksi DB) untuk menemukan pola error. " +
      "Lalu saya lakukan root cause analysis: reproduksi masalah di staging, periksa slow query dengan EXPLAIN ANALYZE, " +
      "dan cek connection pool yang habis. Setelah akar masalah ketemu, saya perbaiki dengan menambah index dan mengatur ulang pool, " +
      "lalu menambahkan alert monitoring serta menulis postmortem agar tidak terulang.";
  } else {
    // Jawaban lemah: dangkal dan umum
    candidate_answer = "Saya akan restart servernya dulu, kalau masih error saya coba lagi nanti.";
  }

  return {
    json: {
      candidate_name: profile.candidate_name,
      position: profile.position,
      claimed_skills: profile.claimed_skills,
      question: q.json.text,
      candidate_answer
    }
  };
});

