// Parse output JSON AI + susun pesan Telegram
// Bersihkan karakter Markdown agar Telegram tidak error "can't parse entities"
const clean_txt = (t) => String(t ?? "").replace(/[`*\[\]]/g, "").replace(/_/g, " ");

return $input.all().map((item, i) => {
  const data = $('Mock Jawaban').all()[i].json;
  const raw = item.json.text || "";
  const clean = raw.replace(/```json|```/g, "").trim();

  let ev;
  try {
    ev = JSON.parse(clean);
  } catch (e) {
    ev = { score: 0, depth: "umum", analysis: "Gagal parsing output AI: " + raw };
  }

  const score = Number(ev.score) || 0;
  let decision;
  if (score >= 75) decision = "LULUS - Lanjut ke wawancara tahap berikutnya";
  else if (score >= 50) decision = "DIPERTIMBANGKAN - Perlu evaluasi tambahan";
  else decision = "TIDAK LULUS";

  const message =
`HASIL SCREENING KANDIDAT

Nama: ${data.candidate_name}
Posisi: ${data.position}
Skill: ${data.claimed_skills.join(", ")}

PERTANYAAN STUDI KASUS:
${clean_txt(data.question)}

JAWABAN KANDIDAT:
${clean_txt(data.candidate_answer)}

HASIL EVALUASI:
Skor: ${score}/100
Kedalaman: ${ev.depth}
Analisis: ${clean_txt(ev.analysis)}

KEPUTUSAN: ${decision}`;

  return { json: { candidate_name: data.candidate_name, score, depth: ev.depth, analysis: ev.analysis, decision, message } };
});
